// Secure Express.js application with security best practices
// This version addresses all security concerns identified in the review

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet.js - Security headers
app.use(helmet());

// 2. CORS configuration - Restrict cross-origin requests
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 4. Body parsing middleware (if needed for POST/PUT requests)
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Remove X-Powered-By header
app.disable('x-powered-by');

// ============================================
// APPLICATION MIDDLEWARE
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Users endpoint - with input validation example
app.get('/users', (req, res) => {
  // Example of simple input validation
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;

  // Validate parameters
  if (limit > 100) {
    return res.status(400).json({ error: 'Limit cannot exceed 100' });
  }
  if (limit < 1) {
    return res.status(400).json({ error: 'Limit must be at least 1' });
  }
  if (offset < 0) {
    return res.status(400).json({ error: 'Offset cannot be negative' });
  }

  // Mock user data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: users.length,
      hasMore: offset + limit < users.length
    }
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `The requested resource ${req.url} was not found on this server.`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);

  // Default error status
  const status = err.statusCode || 500;

  // Sanitize error message for production
  let message = 'Internal Server Error';
  if (process.env.NODE_ENV !== 'production') {
    message = err.message;
  }

  res.status(status).json({
    error: 'Server Error',
    message: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ============================================
// SERVER SETUP
// ============================================

// Use environment variable for port or default to 3000
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Only start server if not in test environment
if (process.env.NODE_ENV !== 'test') {
  app.listen(PORT, HOST, () => {
    console.log(`=================================`);
    console.log(`Secure Server starting...`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Host: ${HOST}`);
    console.log(`Port: ${PORT}`);
    console.log(`=================================`);
    console.log(`Security Features Enabled:`);
    console.log(`- Helmet.js security headers`);
    console.log(`- CORS with restricted origins`);
    console.log(`- Rate limiting (100 req/15 min per IP)`);
    console.log(`- Body parsing with size limits`);
    console.log(`- Request logging`);
    console.log(`- Error handling middleware`);
    console.log(`=================================`);
  });
}

module.exports = app;

// Security test script
// Tests basic security features of the application

const http = require('http');

console.log('=== SECURITY FEATURES TEST ===\n');

// Test configuration
const BASE_URL = 'http://localhost:3000';
const tests = [];

// Helper function to make HTTP requests
function makeRequest(path, method = 'GET', headers = {}) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: path,
      method: method,
      headers: headers
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (err) => {
      reject(err);
    });

    req.end();
  });
}

// Run tests
async function runTests() {
  console.log('1. Testing security headers...');
  try {
    const response = await makeRequest('/health');

    // Check for security headers
    tests.push({
      name: 'X-Powered-By header removed',
      result: !response.headers['x-powered-by'],
      expected: true
    });

    tests.push({
      name: 'X-Content-Type-Options header present',
      result: response.headers['x-content-type-options'] === 'nosniff',
      expected: true
    });

    tests.push({
      name: 'X-Frame-Options header present',
      result: !!response.headers['x-frame-options'],
      expected: true
    });

    console.log('✓ Security headers test completed\n');
  } catch (err) {
    console.log('✗ Server may not be running or not accessible\n');
  }

  console.log('2. Testing CORS headers...');
  try {
    const response = await makeRequest('/health');

    tests.push({
      name: 'CORS headers present',
      result: !!response.headers['access-control-allow-origin'],
      expected: true
    });

    console.log('✓ CORS headers test completed\n');
  } catch (err) {
    console.log('✗ Server may not be running\n');
  }

  console.log('3. Testing rate limiting (this may take a moment)...');
  try {
    // Make multiple requests quickly to trigger rate limiting
    const requests = [];
    for (let i = 0; i < 105; i++) {
      requests.push(makeRequest('/health').catch(() => null));
    }

    const responses = await Promise.all(requests);
    const rateLimitedResponses = responses.filter(r => r && r.statusCode === 429).length;

    tests.push({
      name: 'Rate limiting appears to be working',
      result: rateLimitedResponses > 0,
      expected: true,
      note: `Found ${rateLimitedResponses} rate-limited responses out of 105 requests`
    });

    console.log('✓ Rate limiting test completed\n');
  } catch (err) {
    console.log('✗ Error testing rate limiting\n');
  }

  console.log('4. Testing input validation...');
  try {
    const response = await makeRequest('/users?limit=1000'); // Should be rejected

    tests.push({
      name: 'Input validation for excessive limit',
      result: response.statusCode === 400,
      expected: true
    });

    console.log('✓ Input validation test completed\n');
  } catch (err) {
    console.log('✗ Error testing input validation\n');
  }

  console.log('5. Testing 404 handling...');
  try {
    const response = await makeRequest('/nonexistent');

    tests.push({
      name: '404 handler returns proper status',
      result: response.statusCode === 404,
      expected: true
    });

    console.log('✓ 404 handler test completed\n');
  } catch (err) {
    console.log('✗ Error testing 404 handler\n');
  }

  // Display results
  console.log('=== TEST RESULTS ===\n');

  let passed = 0;
  let failed = 0;

  tests.forEach((test, index) => {
    const status = test.result ? '✓ PASS' : '✗ FAIL';
    if (test.result) passed++;
    else failed++;

    console.log(`${index + 1}. ${test.name}: ${status}`);
    if (test.note) {
      console.log(`   Note: ${test.note}`);
    }
    if (!test.result && test.expected !== undefined) {
      console.log(`   Expected: ${test.expected}, Got: ${test.result}`);
    }
    console.log();
  });

  console.log(`Summary: ${passed} passed, ${failed} failed`);

  if (failed === 0) {
    console.log('\n✅ All security tests passed!');
  } else {
    console.log('\n⚠️  Some security tests failed. Review the implementation.');
  }

  // Recommendations
  console.log('\n=== RECOMMENDED ADDITIONAL TESTS ===');
  console.log('1. Run: npm audit (dependency vulnerabilities)');
  console.log('2. Run: npx snyk test (additional security scanning)');
  console.log('3. Test with OWASP ZAP (penetration testing)');
  console.log('4. Test with burp suite (security scanning)');
  console.log('5. Manual testing of all endpoints');
}

// Run tests if this script is executed directly
if (require.main === module) {
  console.log('Note: Start the server with "npm run dev" before running tests\n');
  runTests().catch(console.error);
}

module.exports = { runTests };

