// Configuration module for the application
// Centralizes all configuration values for better security and maintainability

const config = {
  // Server configuration
  server: {
    port: parseInt(process.env.PORT) || 3000,
    host: process.env.HOST || '0.0.0.0',
    nodeEnv: process.env.NODE_ENV || 'development',
    appName: process.env.APP_NAME || 'Secure Node.js App',
    appVersion: process.env.APP_VERSION || '1.0.0'
  },

  // Security configuration
  security: {
    // CORS settings
    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',') 
        : ['http://localhost:3000', 'http://localhost:8080'],
      allowedMethods: ['GET', 'POST', 'PUT', 'DELETE'] || (process.env.CORS_ALLOWED_METHODS 
        ? process.env.CORS_ALLOWED_METHODS.split(',') 
        : ['GET', 'POST', 'PUT', 'DELETE']),
      allowedHeaders: ['Content-Type', 'Authorization'] || (process.env.CORS_ALLOWED_HEADERS 
        ? process.env.CORS_ALLOWED_HEADERS.split(',') 
        : ['Content-Type', 'Authorization']),
      credentials: process.env.CORS_CREDENTIALS !== 'false', // default true
      maxAge: parseInt(process.env.CORS_MAX_AGE) || 86400 // 24 hours in seconds
    },

    // Rate limiting
    rateLimit: {
      enabled: process.env.RATE_LIMIT_ENABLED !== 'false', // default true
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later'
    },

    // Request settings
    request: {
      bodySizeLimit: process.env.REQUEST_BODY_LIMIT || '10kb',
      urlEncodedExtended: process.env.REQUEST_URL_ENCODED_EXTENDED !== 'false' // default true
    },

    // HTTP headers
    headers: {
      poweredBy: process.env.HTTP_HEADER_POWERED_BY || '', // empty to disable
      hstsMaxAge: parseInt(process.env.HTTP_HSTS_MAX_AGE) || 31536000 // 1 year in seconds
    }
  },

  // Application configuration
  application: {
    // Query parameters
    query: {
      maxLimit: parseInt(process.env.QUERY_MAX_LIMIT) || 100,
      defaultLimit: parseInt(process.env.QUERY_DEFAULT_LIMIT) || 10,
      maxOffset: parseInt(process.env.QUERY_MAX_OFFSET) || 1000
    },

    // Logging
    logging: {
      level: process.env.LOG_LEVEL || 'info',
      format: process.env.LOG_FORMAT || 'combined'
    },

    // Mock data (for development/demo only)
    mockData: {
      enabled: process.env.MOCK_DATA_ENABLED === 'true' || process.env.NODE_ENV === 'development',
      users: [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ]
    },

    // Error handling
    errors: {
      showStack: process.env.SHOW_ERROR_STACK === 'true' || process.env.NODE_ENV === 'development'
    }
  },

  // Validation functions
  validate: function() {
    const errors = [];

    // Validate server configuration
    if (this.server.port < 1 || this.server.port > 65535) {
      errors.push(`Invalid port: ${this.server.port}. Must be between 1 and 65535`);
    }

    // Validate security configuration
    if (this.security.rateLimit.maxRequests < 1) {
      errors.push(`Invalid rate limit max requests: ${this.security.rateLimit.maxRequests}. Must be at least 1`);
    }

    if (this.security.rateLimit.windowMs < 1000) {
      errors.push(`Invalid rate limit window: ${this.security.rateLimit.windowMs}ms. Must be at least 1000ms`);
    }

    // Validate application configuration
    if (this.application.query.maxLimit < 1) {
      errors.push(`Invalid query max limit: ${this.application.query.maxLimit}. Must be at least 1`);
    }

    if (this.application.query.defaultLimit < 1) {
      errors.push(`Invalid query default limit: ${this.application.query.defaultLimit}. Must be at least 1`);
    }

    if (this.application.query.defaultLimit > this.application.query.maxLimit) {
      errors.push(`Default limit (${this.application.query.defaultLimit}) cannot exceed max limit (${this.application.query.maxLimit})`);
    }

    return errors;
  },

  // Helper methods
  isProduction: function() {
    return this.server.nodeEnv === 'production';
  },

  isDevelopment: function() {
    return this.server.nodeEnv === 'development';
  },

  isTest: function() {
    return this.server.nodeEnv === 'test';
  },

  // Get configuration as JSON (for debugging/health checks)
  toJSON: function() {
    return {
      server: {
        ...this.server,
        // Don't expose sensitive information
        host: '***',
        nodeEnv: this.server.nodeEnv
      },
      security: {
        cors: {
          allowedOrigins: this.security.cors.allowedOrigins,
          allowedMethods: this.security.cors.allowedMethods,
          maxAge: this.security.cors.maxAge
        },
        rateLimit: {
          enabled: this.security.rateLimit.enabled,
          windowMs: this.security.rateLimit.windowMs,
          maxRequests: this.security.rateLimit.maxRequests
        },
        request: {
          bodySizeLimit: this.security.request.bodySizeLimit
        }
      },
      application: {
        query: this.application.query,
        logging: this.application.logging,
        mockData: {
          enabled: this.application.mockData.enabled,
          userCount: this.application.mockData.users.length
        }
      }
    };
  }
};

// Validate configuration on startup
const validationErrors = config.validate();
if (validationErrors.length > 0) {
  console.error('Configuration validation errors:');
  validationErrors.forEach(error => console.error(`  - ${error}`));

  // In production, we might want to exit, but in development we can continue with warnings
  if (config.isProduction()) {
    console.error('Exiting due to configuration errors');
    process.exit(1);
  } else {
    console.warn('Continuing with configuration errors (development mode)');
  }
}

// Log configuration in development mode
if (config.isDevelopment()) {
  console.log('Configuration loaded:', JSON.stringify(config.toJSON(), null, 2));
}

module.exports = config;

// Secure Express.js application using centralized configuration
// All hardcoded values replaced with config module references

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const config = require('./config');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet.js - Security headers
app.use(helmet({
  hsts: {
    maxAge: config.security.headers.hstsMaxAge,
    includeSubDomains: true,
    preload: true
  }
}));

// Remove X-Powered-By header
app.disable('x-powered-by');
if (config.security.headers.poweredBy) {
  app.set('x-powered-by', config.security.headers.poweredBy);
}

// 2. CORS configuration
if (config.security.cors.enabled) {
  app.use(cors({
    origin: config.security.cors.allowedOrigins,
    methods: config.security.cors.allowedMethods,
    allowedHeaders: config.security.cors.allowedHeaders,
    credentials: config.security.cors.credentials,
    maxAge: config.security.cors.maxAge
  }));
}

// 3. Rate limiting
if (config.security.rateLimit.enabled) {
  const limiter = rateLimit({
    windowMs: config.security.rateLimit.windowMs,
    max: config.security.rateLimit.maxRequests,
    message: {
      error: config.security.rateLimit.message
    },
    standardHeaders: true,
    legacyHeaders: false
  });
  app.use(limiter);
}

// 4. Body parsing middleware
app.use(express.json({ 
  limit: config.security.request.bodySizeLimit 
}));

app.use(express.urlencoded({ 
  extended: config.security.request.urlEncodedExtended,
  limit: config.security.request.bodySizeLimit 
}));

// ============================================
// APPLICATION MIDDLEWARE
// ============================================

// Request logging middleware
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const url = req.url;
  const ip = req.ip || req.connection.remoteAddress;
  const userAgent = req.get('User-Agent') || 'Unknown';

  console.log(`${timestamp} - ${method} ${url} - IP: ${ip} - UA: ${userAgent.substring(0, 50)}`);
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint with configuration info
app.get('/health', (req, res) => {
  const healthInfo = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    service: {
      name: config.server.appName,
      version: config.server.appVersion,
      environment: config.server.nodeEnv
    },
    config: {
      rateLimit: {
        enabled: config.security.rateLimit.enabled,
        maxRequests: config.security.rateLimit.maxRequests,
        windowMs: config.security.rateLimit.windowMs
      },
      cors: {
        allowedOrigins: config.security.cors.allowedOrigins.length,
        maxAge: config.security.cors.maxAge
      }
    },
    system: {
      nodeVersion: process.version,
      platform: process.platform,
      memory: process.memoryUsage()
    }
  };

  res.json(healthInfo);
});

// Configuration endpoint (development only)
if (config.isDevelopment()) {
  app.get('/config', (req, res) => {
    res.json({
      message: 'Configuration endpoint available in development mode only',
      config: config.toJSON()
    });
  });
}

// Users endpoint with config-based validation
app.get('/users', (req, res) => {
  // Parse query parameters with config defaults
  const limit = parseInt(req.query.limit) || config.application.query.defaultLimit;
  const offset = parseInt(req.query.offset) || 0;

  // Validate against configuration
  if (limit > config.application.query.maxLimit) {
    return res.status(400).json({ 
      error: `Limit cannot exceed ${config.application.query.maxLimit}` 
    });
  }

  if (limit < 1) {
    return res.status(400).json({ 
      error: 'Limit must be at least 1' 
    });
  }

  if (offset < 0) {
    return res.status(400).json({ 
      error: 'Offset cannot be negative' 
    });
  }

  if (offset > config.application.query.maxOffset) {
    return res.status(400).json({ 
      error: `Offset cannot exceed ${config.application.query.maxOffset}` 
    });
  }

  // Get users from mock data or database
  let users = [];
  if (config.application.mockData.enabled) {
    users = config.application.mockData.users;
  } else {
    // In production, this would come from a database
    users = [];
  }

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: users.length,
      hasMore: offset + limit < users.length
    },
    config: {
      maxLimit: config.application.query.maxLimit,
      maxOffset: config.application.query.maxOffset
    }
  });
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.url} was not found on this server.`,
    documentation: 'https://example.com/api-docs'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with contextual information
  const errorContext = {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip || req.connection.remoteAddress,
    error: {
      name: err.name,
      message: err.message,
      stack: config.application.errors.showStack ? err.stack : undefined
    }
  };

  console.error('Application Error:', errorContext);

  // Default error status
  const status = err.statusCode || 500;

  // Prepare response based on environment
  const errorResponse = {
    error: 'Internal Server Error',
    message: config.isProduction() ? 'An unexpected error occurred' : err.message,
    requestId: req.id || Date.now().toString(36) + Math.random().toString(36).substr(2)
  };

  // Add stack trace in development
  if (config.application.errors.showStack) {
    errorResponse.stack = err.stack;
  }

  // Add validation errors if present
  if (err.validationErrors) {
    errorResponse.validationErrors = err.validationErrors;
  }

  res.status(status).json(errorResponse);
});

// ============================================
// SERVER SETUP
// ============================================

// Only start server if not in test environment
if (!config.isTest()) {
  const server = app.listen(config.server.port, config.server.host, () => {
    console.log(`=================================`);
    console.log(`${config.server.appName} v${config.server.appVersion}`);
    console.log(`Environment: ${config.server.nodeEnv}`);
    console.log(`Server: ${config.server.host}:${config.server.port}`);
    console.log(`=================================`);
    console.log(`Security Configuration:`);
    console.log(`- CORS: ${config.security.cors.enabled ? 'Enabled' : 'Disabled'}`);
    console.log(`  Allowed Origins: ${config.security.cors.allowedOrigins.length}`);
    console.log(`- Rate Limiting: ${config.security.rateLimit.enabled ? 'Enabled' : 'Disabled'}`);
    console.log(`  ${config.security.rateLimit.maxRequests} req/${config.security.rateLimit.windowMs/60000} min per IP`);
    console.log(`- Request Size Limit: ${config.security.request.bodySizeLimit}`);
    console.log(`=================================`);
    console.log(`Application Configuration:`);
    console.log(`- Query Max Limit: ${config.application.query.maxLimit}`);
    console.log(`- Mock Data: ${config.application.mockData.enabled ? 'Enabled' : 'Disabled'}`);
    console.log(`- Error Stack: ${config.application.errors.showStack ? 'Shown' : 'Hidden'}`);
    console.log(`=================================`);

    // Validation warnings
    const validationErrors = config.validate();
    if (validationErrors.length > 0 && !config.isProduction()) {
      console.warn('Configuration warnings:');
      validationErrors.forEach(error => console.warn(`  ⚠️  ${error}`));
    }
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
      console.log('Server closed. Exiting process.');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Could not close connections in time. Forcing shutdown.');
      process.exit(1);
    }, 10000);
  });
}

module.exports = { app, config };

