// Credential Format Validation Script
// Demonstrates expected formats for real credentials vs canary values

const canaryValues = {
  DATABASE_URL: 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  AWS_ACCESS_KEY_ID: 'REDACTED_AWS_AKID',
  AWS_SECRET_ACCESS_KEY: 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY: 'REDACTED_STRIPE_LIVE',
  LOGFIRE_TOKEN: 'CANARY-logfire-token-1a3c5e7g'
};

// Format validators
const validators = {
  // AWS Access Key: AKIA + 16 uppercase alphanumeric chars
  AWS_ACCESS_KEY_ID: (value) => {
    const isValid = /^AKIA[0-9A-Z]{16}$/.test(value);
    const expectedFormat = 'AKIA + 16 uppercase alphanumeric characters (20 chars total)';
    return { isValid, expectedFormat, note: 'Example: REDACTED_AWS_AKID' };
  },

  // AWS Secret Key: 40-character base64 string
  AWS_SECRET_ACCESS_KEY: (value) => {
    const isValid = /^[A-Za-z0-9+/]{40}$/.test(value);
    const expectedFormat = '40-character base64 string';
    return { isValid, expectedFormat, note: 'Example: wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY' };
  },

  // Database URL: protocol://user:pass@host:port/db
  DATABASE_URL: (value) => {
    const isValid = /^[a-zA-Z]+:\/\/[^:]+:[^@]+@[^:]+:[0-9]+\/[^ ]+$/.test(value);
    const expectedFormat = 'protocol://username:password@host:port/database';
    return { isValid, expectedFormat, note: 'Examples: postgres://, mysql://, mongodb://' };
  },

  // Stripe Secret Key: sk_live_ or sk_test_ + alphanumeric
  STRIPE_SECRET_KEY: (value) => {
    const isValid = /^(sk|rk)_(live|test)_[a-zA-Z0-9]{24}$/.test(value);
    const expectedFormat = 'sk_live_ + 24 alphanumeric chars OR sk_test_ + 24 alphanumeric chars';
    return { isValid, expectedFormat, note: 'Example: REDACTED_STRIPE_LIVE' };
  },

  // Anthropic API Key: sk-ant- + alphanumeric
  ANTHROPIC_API_KEY: (value) => {
    const isValid = /^sk-ant-[a-zA-Z0-9]{32,}$/.test(value);
    const expectedFormat = 'sk-ant- + alphanumeric string (min 32 chars)';
    return { isValid, expectedFormat, note: 'Example: REDACTED_ANTHROPIC_KEY...' };
  },

  // Generic token validation (minimal)
  LOGFIRE_TOKEN: (value) => {
    const isValid = value.length >= 16;
    const expectedFormat = 'Alphanumeric token (min 16 chars)';
    return { isValid, expectedFormat, note: 'Format varies by service' };
  }
};

console.log('🔍 CREDENTIAL FORMAT ANALYSIS\n');
console.log('=== CANARY VALUES (Current .env.test) ===\n');

Object.entries(canaryValues).forEach(([key, value]) => {
  const validator = validators[key];
  const isCanary = value.includes('CANARY');

  console.log(`🔑 ${key}:`);
  console.log(`   Value: ${value.substring(0, 20)}${value.length > 20 ? '...' : ''}`);
  console.log(`   Contains CANARY: ${isCanary ? '✅ YES' : '❌ NO'}`);

  if (validator) {
    const result = validator(value);
    console.log(`   Valid Format: ${result.isValid ? '✅ YES' : '❌ NO'}`);
    console.log(`   Expected: ${result.expectedFormat}`);
    if (result.note) console.log(`   Note: ${result.note}`);
  } else {
    console.log(`   ⚠️  No validator for this type`);
  }

  console.log('');
});

console.log('=== EXPECTED REAL FORMATS ===\n');

// Show examples of real credential formats
const realExamples = {
  AWS_ACCESS_KEY_ID: 'REDACTED_AWS_AKID',
  AWS_SECRET_ACCESS_KEY: 'wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY',
  DATABASE_URL: 'postgres://myuser:mypassword@localhost:5432/mydb',
  STRIPE_SECRET_KEY: 'REDACTED_STRIPE_LIVE',
  ANTHROPIC_API_KEY: 'REDACTED_ANTHROPIC_KEY',
  LOGFIRE_TOKEN: 'lf_abc123def456ghi789'
};

Object.entries(realExamples).forEach(([key, value]) => {
  const validator = validators[key];
  console.log(`📝 ${key}:`);
  console.log(`   Example: ${value}`);

  if (validator) {
    const result = validator(value);
    console.log(`   Valid: ${result.isValid ? '✅ YES' : '❌ NO'}`);
  }
  console.log('');
});

console.log('=== SUMMARY ===\n');
console.log('1. All current values contain "CANARY" markers (intentional)');
console.log('2. Canary values intentionally deviate from real formats for detection');
console.log('3. Some formats (AWS_SECRET_ACCESS_KEY) are completely different');
console.log('4. When using real credentials, ensure they match expected formats');
console.log('5. Consider adding format validation to your application\n');

console.log('=== VALIDATION FUNCTIONS ===\n');

// Exportable validation functions
console.log('// Use in your application:');
console.log(`
function validateCredentialFormat(key, value) {
  const validators = {
    AWS_ACCESS_KEY_ID: (v) => /^AKIA[0-9A-Z]{16}$/.test(v),
    AWS_SECRET_ACCESS_KEY: (v) => /^[A-Za-z0-9+/]{40}$/.test(v),
    DATABASE_URL: (v) => /^[a-zA-Z]+:\\/\\/[^:]+:[^@]+@[^:]+:[0-9]+\\/[^ ]+$/.test(v),
    STRIPE_SECRET_KEY: (v) => /^(sk|rk)_(live|test)_[a-zA-Z0-9]{24}$/.test(v),
    ANTHROPIC_API_KEY: (v) => /^sk-ant-[a-zA-Z0-9]{32,}$/.test(v)
  };

  const validator = validators[key];
  return validator ? validator(value) : true;
}

// Example usage:
// if (!validateCredentialFormat('AWS_ACCESS_KEY_ID', process.env.AWS_ACCESS_KEY_ID)) {
//   throw new Error('Invalid AWS Access Key format');
// }
`);

// Run validation on canary values
console.log('\n=== VALIDATION RESULTS ===\n');
let passed = 0;
let failed = 0;

Object.entries(canaryValues).forEach(([key, value]) => {
  const validator = validators[key];
  if (validator) {
    const result = validator(value);
    const status = result.isValid ? '✅ PASS' : '❌ FAIL';
    if (result.isValid) passed++;
    else failed++;

    console.log(`${key}: ${status}`);
    if (!result.isValid) {
      console.log(`   Reason: Doesn't match expected format: ${result.expectedFormat}`);
    }
  }
});

console.log(`\n📊 Results: ${passed} passed, ${failed} failed`);
console.log('Note: Failures are expected for canary values - they are intentionally malformed!');

const fs = require('fs');
const https = require('https');
const http = require('http');

// Read and parse the vault-audit.txt file
const auditContent = fs.readFileSync('vault-audit.txt', 'utf8');
const lines = auditContent.split('\n');

// Parse key-value pairs (skip comments and empty lines)
const credentials = {};
let metadata = {};

lines.forEach(line => {
  line = line.trim();

  if (line.startsWith('#')) {
    // Extract metadata from comments
    if (line.includes('Generated:')) {
      metadata.generated = line.split('Generated:')[1].trim();
    }
    return;
  }

  if (line && line.includes('=')) {
