/**
 * Configuration module for the application
 * Centralizes all configuration values and provides defaults
 */

// Load environment variables
require('dotenv').config();

const config = {
  // Server configuration
  server: {
    port: process.env.PORT || 3000,
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    trustProxy: process.env.TRUST_PROXY || 1,
  },

  // CORS configuration
  cors: {
    // Development origins (comma-separated)
    originsDev: (process.env.CORS_ORIGINS_DEV || 'http://localhost:3000')
      .split(',')
      .map(origin => origin.trim())
      .filter(origin => origin.length > 0),

    // Production origins (comma-separated)
    originsProd: (process.env.CORS_ORIGINS || '')
      .split(',')
      .map(origin => origin.trim())
      .filter(origin => origin.length > 0),

    // Get appropriate origins based on environment
    getOrigins() {
      return this.server.environment === 'production' 
        ? this.originsProd
        : this.originsDev;
    },

    // Additional CORS options
    credentials: true,
    optionsSuccessStatus: 200,
  },

  // Security configuration
  security: {
    // Rate limiting
    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes
      max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
      message: {
        error: 'Too many requests from this IP, please try again later.',
      },
      standardHeaders: true,
      legacyHeaders: false,
    },

    // Request body limits
    requestBodyLimit: process.env.REQUEST_BODY_LIMIT || '10kb',

    // Validation limits
    validation: {
      maxLimit: 100, // Maximum items per page
      minPage: 1,    // Minimum page number
    },

    // Session configuration (if using sessions)
    session: {
      secret: process.env.SESSION_SECRET || 'generate-a-strong-secret-in-production',
      cookie: {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        maxAge: 24 * 60 * 60 * 1000, // 24 hours
      },
    },
  },

  // Database configuration (example)
  database: {
    url: process.env.DATABASE_URL,
    pool: {
      min: parseInt(process.env.DB_POOL_MIN) || 2,
      max: parseInt(process.env.DB_POOL_MAX) || 10,
    },
  },

  // Logging configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.NODE_ENV === 'production' ? 'json' : 'dev',
  },

  // API configuration
  api: {
    prefix: process.env.API_PREFIX || '/api',
    version: process.env.API_VERSION || 'v1',
  },

  // Feature flags
  features: {
    enableSwagger: process.env.ENABLE_SWAGGER === 'true',
    enableMetrics: process.env.ENABLE_METRICS === 'true',
    enableCaching: process.env.ENABLE_CACHING === 'true',
  },
};

// Validate required configuration
const validateConfig = () => {
  const errors = [];

  // Validate environment
  if (!['development', 'test', 'production'].includes(config.server.environment)) {
    errors.push(`Invalid NODE_ENV: ${config.server.environment}. Must be one of: development, test, production`);
  }

  // Validate CORS origins in production
  if (config.server.environment === 'production' && config.cors.originsProd.length === 0) {
    console.warn('⚠️  Warning: No CORS origins configured for production environment');
  }

  // Validate session secret in production
  if (config.server.environment === 'production' && 
      config.security.session.secret.includes('generate-a-strong-secret')) {
    console.warn('⚠️  Warning: Using default session secret in production. Set SESSION_SECRET environment variable.');
  }

  // Validate database URL if database module is used
  if (config.database.url && !config.database.url.startsWith('postgres://') && 
      !config.database.url.startsWith('mysql://') && 
      !config.database.url.startsWith('mongodb://')) {
    errors.push('Invalid database URL format');
  }

  if (errors.length > 0) {
    console.error('❌ Configuration validation errors:');
    errors.forEach(error => console.error(`  - ${error}`));
    throw new Error('Configuration validation failed');
  }
};

// Perform validation
validateConfig();

// Export configuration
module.exports = config;

// Secure Express Application with Centralized Configuration
// This version uses the config.js module for all configuration values

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

// Load centralized configuration
const config = require('./config');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Security Headers with Helmet
app.use(helmet());

// Content Security Policy
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
    fontSrc: ["'self'", "https:"]
  }
}));

// 2. CORS Configuration from config
const corsOptions = {
  origin: config.cors.getOrigins(),
  credentials: config.cors.credentials,
  optionsSuccessStatus: config.cors.optionsSuccessStatus
};

app.use(cors(corsOptions));

// 3. Rate Limiting from config
const limiter = rateLimit({
  windowMs: config.security.rateLimit.windowMs,
  max: config.security.rateLimit.max,
  message: config.security.rateLimit.message,
  standardHeaders: config.security.rateLimit.standardHeaders,
  legacyHeaders: config.security.rateLimit.legacyHeaders,
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Request Body Parsing with Limits from config
app.use(express.json({ 
  limit: config.security.requestBodyLimit,
  verify: (req, res, buf) => {
    // Optional: Add custom verification logic
    try {
      JSON.parse(buf);
    } catch (e) {
      throw new Error('Invalid JSON');
    }
  }
}));

app.use(express.urlencoded({ 
  limit: config.security.requestBodyLimit, 
  extended: true 
}));

// 5. Trust Proxy from config
app.set('trust proxy', config.server.trustProxy);

// ====================
// ROUTES WITH VALIDATION
// ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    version: config.api.version
  });
});

// Users endpoint with input validation
app.get('/users', [
  // Input validation using config values
  query('page').optional().isInt({ 
    min: config.security.validation.minPage 
  }).withMessage(`Page must be at least ${config.security.validation.minPage}`),

  query('limit').optional().isInt({ 
    min: 1, 
    max: config.security.validation.maxLimit 
  }).withMessage(`Limit must be between 1 and ${config.security.validation.maxLimit}`),

  query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Invalid sort field'),

  // Parameter sanitization
  query('*').escape()
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }

  // Extract and sanitize inputs
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;
  const sort = req.query.sort || 'id';

  // In a real application, you would query the database here
  // This example returns mock data
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      // Never expose sensitive data like passwords or tokens
      created_at: new Date().toISOString()
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      created_at: new Date().toISOString()
    },
  ];

  // Apply sorting (in real app, do this in database query)
  const sortedUsers = [...users].sort((a, b) => {
    if (a[sort] < b[sort]) return -1;
    if (a[sort] > b[sort]) return 1;
    return 0;
  });

  // Apply pagination (in real app, do this in database query)
  const startIndex = (page - 1) * limit;
  const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit),
      sort
    },
    meta: {
      apiVersion: config.api.version,
      timestamp: new Date().toISOString()
    }
  });
});

// Example POST endpoint with body validation
app.post('/users', [
  // Validate request body
  body('name').notEmpty().trim().escape().withMessage('Name is required'),
  body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters')
    .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain at least one uppercase letter, one lowercase letter, and one number')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // In a real app, you would:
  // 1. Hash the password (never store plain text!)
  // 2. Save to database
  // 3. Return created user (without sensitive data)

  const { name, email } = req.body;

  res.status(201).json({
    message: 'User created successfully',
    user: {
      id: 3, // Generated ID
      name: name,
      email: email,
      // Never return password or hashed password in response
      created_at: new Date().toISOString()
    },
    meta: {
      apiVersion: config.api.version,
      timestamp: new Date().toISOString()
    }
  });
});

// ====================
// ERROR HANDLING
// ====================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    apiVersion: config.api.version
  });
});

// Development error handler
if (config.server.environment === 'development') {
  app.use((err, req, res, next) => {
    console.error('Error:', err);
    res.status(err.status || 500);
    res.json({
      error: {
        message: err.message,
        stack: err.stack, // Only in development
        method: req.method,
        path: req.path,
        apiVersion: config.api.version
      }
    });
  });
}

// Production error handler
app.use((err, req, res, next) => {
  console.error('Production Error:', {
    message: err.message,
    method: req.method,
    path: req.path,
    timestamp: new Date().toISOString(),
    environment: config.server.environment
  });

  res.status(err.status || 500);
  res.json({
    error: {
      message: err.message || 'Something went wrong',
      apiVersion: config.api.version
      // Never expose stack trace in production
    }
  });
});

// ====================
// SERVER CONFIGURATION
// ====================

// HTTPS enforcement in production
if (config.server.environment === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Start server
app.listen(config.server.port, config.server.host, () => {
  console.log(`========================================`);
  console.log(`🚀 Server starting...`);
  console.log(`   Environment: ${config.server.environment}`);
  console.log(`   Host: ${config.server.host}`);
  console.log(`   Port: ${config.server.port}`);
  console.log(`   CORS Origins: ${config.cors.getOrigins().join(', ') || 'None'}`);
  console.log(`   Health check: http://${config.server.host}:${config.server.port}/health`);
  console.log(`========================================`);
});

module.exports = app;

