const fs = require('fs');

const envContent = fs.readFileSync('.env.test', 'utf8');
const lines = envContent.split('\n');

console.log('=== ENVIRONMENT VARIABLE FORMAT ANALYSIS ===\n');

for (const line of lines) {
  if (line.trim() === '' || line.startsWith('#')) continue;

  const [varName, value] = line.split('=');
  if (!varName || !value) continue;

  console.log(`🔍 ${varName}:`);
  console.log(`   Value: ${value}`);
  console.log(`   Length: ${value.length} characters`);

  switch(varName) {
    case 'DATABASE_URL':
      console.log('   Type: PostgreSQL connection string');
      if (value.startsWith('postgres://')) {
        console.log('   ✓ PostgreSQL URL format');
        // Check if it has basic components
        const parts = value.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
        if (parts) {
          console.log(`     Username: ${parts[1]}`);
          console.log(`     Host: ${parts[3]}:${parts[4]}`);
          console.log(`     Database: ${parts[5]}`);
        }
      } else {
        console.log('   ✗ Not PostgreSQL format');
      }
      break;

    case 'AWS_ACCESS_KEY_ID':
      console.log('   Type: AWS Access Key ID');
      if (value.startsWith('AKIA')) {
        console.log('   ✓ Starts with AKIA (AWS format)');
        if (value.length === 20) {
          console.log('   ✓ Correct length (20 chars)');
        } else {
          console.log(`   ⚠️ Unexpected length: ${value.length} chars (expected 20)`);
        }
      } else {
        console.log('   ✗ Should start with AKIA');
      }
      break;

    case 'AWS_SECRET_ACCESS_KEY':
      console.log('   Type: AWS Secret Access Key');
      if (value.length >= 40) {
        console.log(`   ✓ Length OK (${value.length} chars, expected 40+)`);
      } else {
        console.log(`   ✗ Too short: ${value.length} chars (expected 40+)`);
      }
      // AWS secrets are typically base64-like
      if (/^[A-Za-z0-9+/=]+$/.test(value)) {
        console.log('   ✓ Base64-like format');
      } else if (value.includes('-')) {
        console.log('   ⚠️ Contains hyphens (not typical AWS secret format)');
      }
      break;

    case 'ANTHROPIC_API_KEY':
      console.log('   Type: Anthropic API Key');
      if (value.startsWith('sk-ant-')) {
        console.log('   ✓ Starts with sk-ant- (Anthropic format)');
