// Secure version of app.js with security improvements
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// 1. Security headers using Helmet
app.use(helmet());

// 2. Configure CORS properly
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Whitelist your domains
    : ['http://localhost:3000'], // Development
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// 6. Input validation middleware (basic example)
const validateGetParams = (req, res, next) => {
  // Add parameter validation logic here
  // Example: Ensure no suspicious characters in query params
  next();
};

// Secure health endpoint with minimal information
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    uptime: process.uptime(),
    timestamp: new Date().toISOString() 
  });
});

// Secure users endpoint with authentication check
const requireAuth = (req, res, next) => {
  // In a real app, implement proper authentication
  // This is just a placeholder
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  next();
};

app.get('/users', requireAuth, validateGetParams, (req, res) => {
  // Return minimal necessary user data
  res.json([
    { id: 1, name: 'Alice' }, // Removed email for privacy
    { id: 2, name: 'Bob' },
  ]);
});

// 7. Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    // Don't expose detailed error info in production
    message: process.env.NODE_ENV === 'development' ? err.message : undefined
  });
});

// 8. 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

