// Secure version of app.js with ALL configurable values as environment variables
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Load environment variables with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const CORS_ORIGIN = process.env.CORS_ORIGIN || 'https://yourdomain.com';
const CORS_ORIGIN_DEV = process.env.CORS_ORIGIN_DEV || 'http://localhost:3000';
const CORS_SUCCESS_STATUS = parseInt(process.env.CORS_SUCCESS_STATUS) || 200;
const RATE_LIMIT_WINDOW = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000);
const RATE_LIMIT_MAX = parseInt(process.env.RATE_LIMIT_MAX) || 100;
const BODY_SIZE_LIMIT = process.env.BODY_SIZE_LIMIT || '10kb';
