// Centralized configuration management with environment variables
// This module provides typed access to all environment variables with validation

const config = {
  // Server Configuration
  port: parseInt(process.env.PORT) || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  logLevel: process.env.LOG_LEVEL || 'info',

  // Security Configuration
  cors: {
    origin: process.env.CORS_ORIGIN || 'https://yourdomain.com',
    originDev: process.env.CORS_ORIGIN_DEV || 'http://localhost:3000',
    successStatus: parseInt(process.env.CORS_SUCCESS_STATUS) || 200,
  },

  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes
    max: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  },

  bodySizeLimit: process.env.BODY_SIZE_LIMIT || '10kb',

  // Application Configuration
  appName: process.env.APP_NAME || 'Secure Express App',
  appVersion: process.env.APP_VERSION || '1.0.0',
  apiPrefix: process.env.API_PREFIX || '/api/v1',

  // Validation configuration
  validation: {
    maxQueryParams: parseInt(process.env.MAX_QUERY_PARAMS) || 20,
    maxQueryLength: parseInt(process.env.MAX_QUERY_LENGTH) || 100,
  },

  // Feature flags
  features: {
    disableAuth: process.env.DISABLE_AUTH === 'true',
    enableMetrics: process.env.ENABLE_METRICS === 'true',
    debugMode: process.env.DEBUG_MODE === 'true',
  },

  // Methods to get environment-specific values
  getCorsOrigins() {
    return this.nodeEnv === 'production' 
      ? [this.cors.origin]
      : [this.cors.originDev];
  },

  getRateLimitWindowMinutes() {
    return Math.floor(this.rateLimit.windowMs / 60000);
  },

  isProduction() {
    return this.nodeEnv === 'production';
  },

  isDevelopment() {
    return this.nodeEnv === 'development';
  },

  isTesting() {
    return this.nodeEnv === 'test';
  },

  // Validation methods
  validateConfig() {
    const errors = [];

    // Validate port
    if (this.port < 1 || this.port > 65535) {
      errors.push(`Invalid PORT: ${this.port}. Must be between 1 and 65535`);
    }

    // Validate NODE_ENV
    const validEnvs = ['development', 'production', 'test'];
    if (!validEnvs.includes(this.nodeEnv)) {
      errors.push(`Invalid NODE_ENV: ${this.nodeEnv}. Valid values: ${validEnvs.join(', ')}`);
    }

    // Validate rate limit
    if (this.rateLimit.max < 1) {
      errors.push(`Invalid RATE_LIMIT_MAX: ${this.rateLimit.max}. Must be at least 1`);
    }

    if (this.rateLimit.windowMs < 1000) {
      errors.push(`Invalid RATE_LIMIT_WINDOW_MS: ${this.rateLimit.windowMs}. Must be at least 1000ms`);
    }

    // Validate body size limit
    const bodySizeRegex = /^(\d+)(kb|mb|gb)$/i;
    if (!bodySizeRegex.test(this.bodySizeLimit)) {
      errors.push(`Invalid BODY_SIZE_LIMIT: ${this.bodySizeLimit}. Must be format like '10kb', '1mb', etc.`);
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }

    return true;
  },

  // Get sanitized config (for logging, not exposing secrets)
  getSanitizedConfig() {
    return {
      port: this.port,
      nodeEnv: this.nodeEnv,
      logLevel: this.logLevel,
      cors: {
        allowedOrigins: this.getCorsOrigins(),
        successStatus: this.cors.successStatus,
      },
      rateLimit: {
        windowMinutes: this.getRateLimitWindowMinutes(),
        maxRequests: this.rateLimit.max,
      },
      bodySizeLimit: this.bodySizeLimit,
      appName: this.appName,
      appVersion: this.appVersion,
      features: this.features,
    };
  },

  // Log configuration on startup
  logStartupConfig() {
    console.log('=================================');
    console.log('Application Configuration:');
    console.log('=================================');
    console.log(`App Name: ${this.appName}`);
    console.log(`Version: ${this.appVersion}`);
    console.log(`Environment: ${this.nodeEnv}`);
    console.log(`Port: ${this.port}`);
    console.log(`Log Level: ${this.logLevel}`);
    console.log(`CORS Origins: ${this.getCorsOrigins().join(', ')}`);
    console.log(`Rate Limit: ${this.rateLimit.max} requests/${this.getRateLimitWindowMinutes()}min`);
    console.log(`Body Size Limit: ${this.bodySizeLimit}`);
    console.log(`Features:`);
    console.log(`  - Auth Disabled: ${this.features.disableAuth}`);
    console.log(`  - Debug Mode: ${this.features.debugMode}`);
    console.log(`  - Metrics Enabled: ${this.features.enableMetrics}`);
    console.log('=================================');
  }
};

// Validate configuration on module load
try {
  config.validateConfig();
} catch (error) {
  console.error('❌ Configuration validation error:', error.message);
  console.error('Please check your environment variables.');
  process.exit(1);
}

module.exports = config;

