// Secure version of app.js with security improvements
// This demonstrates how to fix the identified security issues

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load environment variables from .env file (if present)
// Note: In production, use proper secret management
require('dotenv').config();

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration - restrict origins
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : ['http://localhost:3000']; // Default for development

app.use(cors({
  origin: function(origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) === -1) {
      const msg = 'The CORS policy for this site does not allow access from the specified Origin.';
      return callback(new Error(msg), false);
    }
    return callback(null, true);
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key']
}));

// 3. Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit JSON request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============ AUTHENTICATION MIDDLEWARE ============

// Simple API key authentication (replace with JWT/OAuth in production)
const authenticate = (req, res, next) => {
  // Get API key from headers
  const apiKey = req.headers['x-api-key'] || req.query.apiKey;

  // In production, validate against database or secret service
  const validApiKeys = process.env.API_KEYS 
    ? process.env.API_KEYS.split(',') 
    : ['development-key']; // Default for development

  if (!apiKey || !validApiKeys.includes(apiKey)) {
    return res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Valid API key is required'
    });
  }

  // Add user/request info to req object (in production, decode JWT here)
  req.user = {
    id: 'authenticated-user',
    permissions: ['read:users'] // Example permissions
  };

  next();
};

// ============ ROUTES ============

// Public health endpoint (no authentication required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.VERSION || '1.0.0',
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint (authentication required)
app.get('/users', authenticate, (req, res) => {
  // Check permissions (example - implement proper RBAC in production)
  if (!req.user.permissions.includes('read:users')) {
    return res.status(403).json({ 
      error: 'Forbidden',
      message: 'Insufficient permissions to access users'
    });
  }

  // Return mock user data (in production, fetch from database)
  res.json([
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: '2024-01-01T00:00:00Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: '2024-01-02T00:00:00Z'
    },
  ]);
});

// Example of input validation with query parameters
app.get('/users/:id', authenticate, (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // Input validation
  if (isNaN(userId) || userId <= 0) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format'
    });
  }

  // In production: fetch user by ID with proper error handling
  if (userId === 1) {
    res.json({ 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: '2024-01-01T00:00:00Z'
    });
  } else if (userId === 2) {
    res.json({ 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: '2024-01-02T00:00:00Z'
    });
  } else {
    res.status(404).json({ 
      error: 'Not Found',
      message: `User with ID ${userId} not found`
    });
  }
});

// ============ ERROR HANDLING ============

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
    requestId: req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9)
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============ SERVER SETUP ============

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

app.listen(PORT, HOST, () => {
  console.log(`🔒 Secure server running on http://${HOST}:${PORT}`);
  console.log(`📊 Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`🔐 Authentication: ${process.env.API_KEYS ? 'Enabled' : 'Disabled (development mode)'}`);
  console.log(`🌐 Allowed origins: ${allowedOrigins.join(', ')}`);
});

module.exports = app;

