/**
 * Configuration Management
 * 
 * Best practices for managing configuration in Node.js applications:
 * 1. All configuration externalized to environment variables
 * 2. Sensible defaults for development
 * 3. Validation of required configuration
 * 4. Type safety and documentation
 */

const Joi = require('joi');

// Define configuration schema with validation
const configSchema = Joi.object({
  // Server configuration
  server: {
    port: Joi.number().port().default(3000).description('Port to listen on'),
    host: Joi.string().hostname().default('0.0.0.0').description('Host to bind to'),
    environment: Joi.string().valid('development', 'test', 'production').default('development')
      .description('Application environment'),
    version: Joi.string().default('1.0.0').description('Application version'),
  },

  // Security configuration
  security: {
    apiKeys: Joi.array().items(Joi.string().min(10)).default(['development-key'])
      .description('Valid API keys (comma-separated in env var)')
      .when('server.environment', {
        is: 'production',
        then: Joi.array().min(1).required(),
      }),

    rateLimit: {
      windowMs: Joi.number().min(60000).default(15 * 60 * 1000) // 15 minutes
        .description('Rate limiting window in milliseconds'),
      maxRequests: Joi.number().min(1).default(100)
        .description('Maximum requests per window per IP'),
    },

    cors: {
      allowedOrigins: Joi.array().items(Joi.string().uri({ scheme: ['http', 'https'] }))
        .default(['http://localhost:3000'])
        .description('Allowed CORS origins (comma-separated in env var)'),
    },

    request: {
      bodyLimit: Joi.string().pattern(/^\d+(kb|mb|gb)$/).default('10kb')
        .description('Maximum request body size'),
    },
  },

  // Data configuration
  data: {
    testEmails: Joi.array().items(Joi.string().email()).default([
      'test.user.1@example.com',
      'test.user.2@example.com'
    ]).description('Test email addresses for mock data'),

    pagination: {
      defaultLimit: Joi.number().min(1).max(100).default(20)
        .description('Default pagination limit'),
      maxLimit: Joi.number().min(1).max(1000).default(100)
        .description('Maximum pagination limit'),
    },
  },

  // Logging configuration
  logging: {
    level: Joi.string().valid('error', 'warn', 'info', 'debug', 'trace')
      .default('info').description('Log level'),
    format: Joi.string().valid('json', 'pretty').default('json')
      .description('Log format'),
  },
});

// Parse environment variables
const envConfig = {
  server: {
    port: parseInt(process.env.PORT || '3000', 10),
    host: process.env.HOST || '0.0.0.0',
    environment: process.env.NODE_ENV || 'development',
    version: process.env.VERSION || '1.0.0',
  },

  security: {
    apiKeys: process.env.API_KEYS 
      ? process.env.API_KEYS.split(',').map(key => key.trim())
      : ['development-key'],

    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || (15 * 60 * 1000).toString(), 10),
      maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10),
    },

    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS 
        ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
        : ['http://localhost:3000'],
    },

    request: {
      bodyLimit: process.env.BODY_LIMIT || '10kb',
    },
  },

  data: {
    testEmails: process.env.TEST_EMAILS 
      ? process.env.TEST_EMAILS.split(',').map(email => email.trim())
      : ['test.user.1@example.com', 'test.user.2@example.com'],

    pagination: {
      defaultLimit: parseInt(process.env.PAGINATION_DEFAULT_LIMIT || '20', 10),
      maxLimit: parseInt(process.env.PAGINATION_MAX_LIMIT || '100', 10),
    },
  },

  logging: {
    level: process.env.LOG_LEVEL || 'info',
    format: process.env.LOG_FORMAT || 'json',
  },
};

// Validate configuration
const { value: config, error } = configSchema.validate(envConfig, {
  abortEarly: false,
  allowUnknown: false,
  stripUnknown: true,
});

// Handle validation errors
if (error) {
  const errorMessages = error.details.map(detail => detail.message).join(', ');
  throw new Error(`Configuration validation failed: ${errorMessages}`);
}

// Log configuration (without sensitive data)
if (config.server.environment === 'development') {
  console.log('Configuration loaded:', {
    server: config.server,
    security: {
      ...config.security,
      apiKeys: config.security.apiKeys.map(() => '***'), // Mask API keys
    },
    data: {
      ...config.data,
      testEmails: config.data.testEmails,
    },
    logging: config.logging,
  });
}

// Export configuration
module.exports = config;

// Helper function to get configuration value with path
module.exports.get = (path, defaultValue) => {
  const keys = path.split('.');
  let current = config;

  for (const key of keys) {
    if (current[key] === undefined) {
      return defaultValue;
    }
    current = current[key];
  }

  return current;
};

// Check if running in production
module.exports.isProduction = () => config.server.environment === 'production';
module.exports.isDevelopment = () => config.server.environment === 'development';
module.exports.isTest = () => config.server.environment === 'test';

// Application using externalized configuration
// Demonstrates best practices for configuration management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Load configuration (throws error if validation fails)
const config = require('./config');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: config.isProduction() ? {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  } : false, // Disable HSTS in development for localhost
}));

// 2. CORS configuration
app.use(cors({
  origin: function(origin, callback) {
    if (!origin) return callback(null, true);

    if (config.security.cors.allowedOrigins.includes(origin)) {
      return callback(null, true);
    }

    // Log unauthorized origins in production
    if (config.isProduction()) {
      console.warn(`Unauthorized CORS request from origin: ${origin}`);
    }

    const msg = 'The CORS policy for this site does not allow access from the specified Origin.';
    return callback(new Error(msg), false);
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key'],
}));

// 3. Rate limiting with configurable values
const limiter = rateLimit({
  windowMs: config.security.rateLimit.windowMs,
  max: config.security.rateLimit.maxRequests,
  message: {
    error: 'Rate limit exceeded',
    message: `Too many requests from this IP, please try again after ${Math.round(config.security.rateLimit.windowMs / 60000)} minutes`
  },
  standardHeaders: true,
  legacyHeaders: false,

  // Skip rate limiting for certain paths (optional)
  skip: (req) => {
    // Skip health checks from load balancers
    return req.path === '/health' && req.get('user-agent')?.includes('ELB-HealthChecker');
  },
});

app.use(limiter);

// 4. Body parsing with configurable limits
app.use(express.json({ limit: config.security.request.bodyLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.security.request.bodyLimit 
}));

// ============ AUTHENTICATION MIDDLEWARE ============

const authenticate = (req, res, next) => {
  const apiKey = req.headers['x-api-key'] || req.query.apiKey;

  if (!apiKey || !config.security.apiKeys.includes(apiKey)) {
    return res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Valid API key is required',
      hint: config.isDevelopment() 
        ? `Development keys: ${config.security.apiKeys.map(() => '***').join(', ')}`
        : undefined
    });
  }

  req.user = {
    id: 'authenticated-user',
    permissions: ['read:users'],
    environment: config.server.environment,
  };

  next();
};

// ============ ROUTES ============

// Public health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: config.server.version,
    environment: config.server.environment,
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    config: config.isDevelopment() ? {
      server: config.server,
      security: {
        ...config.security,
        apiKeys: config.security.apiKeys.map(() => '***'), // Mask in response
      },
    } : undefined, // Only expose config in development
  });
});

// Configuration endpoint (development only)
if (config.isDevelopment()) {
  app.get('/config', (req, res) => {
    res.json({
      server: config.server,
      security: {
        ...config.security,
        apiKeys: config.security.apiKeys.map(() => '***'),
      },
      data: config.data,
      logging: config.logging,
    });
  });
}

// Protected users endpoint with mock data from config
app.get('/users', authenticate, (req, res) => {
  // Use test emails from configuration
  const users = config.data.testEmails.map((email, index) => ({
    id: index + 1,
    name: `User ${index + 1}`,
    email: email,
    createdAt: new Date(Date.now() - (index * 86400000)).toISOString(), // Daily offset
    environment: config.server.environment,
  }));

  // Apply pagination (example)
  const page = parseInt(req.query.page) || 1;
  const limit = Math.min(
    parseInt(req.query.limit) || config.data.pagination.defaultLimit,
    config.data.pagination.maxLimit
  );
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;

  const paginatedUsers = users.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      totalPages: Math.ceil(users.length / limit),
      hasNext: endIndex < users.length,
      hasPrevious: startIndex > 0,
    },
    environment: config.server.environment,
  });
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
    environment: config.server.environment,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with configuration context
  console.error({
    timestamp: new Date().toISOString(),
    environment: config.server.environment,
    level: 'error',
    message: err.message,
    stack: config.isDevelopment() ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Determine status code
  const statusCode = err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: statusCode === 500 ? 'Internal Server Error' : err.name || 'Error',
    message: config.isProduction() && statusCode === 500
      ? 'An unexpected error occurred'
      : err.message,
    environment: config.server.environment,
    requestId: req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9),
  };

  // Add stack trace only in development
  if (config.isDevelopment()) {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// ============ SERVER SETUP ============

const server = app.listen(config.server.port, config.server.host, () => {
  console.log({
    timestamp: new Date().toISOString(),
    level: 'info',
    message: `Server started`,
    environment: config.server.environment,
    host: config.server.host,
    port: config.server.port,
    version: config.server.version,
    security: {
      apiKeysConfigured: config.security.apiKeys.length > 0,
      rateLimit: config.security.rateLimit,
      corsOrigins: config.security.cors.allowedOrigins.length,
    },
  });
});

// Graceful shutdown
const shutdown = (signal) => {
  console.log({
    timestamp: new Date().toISOString(),
    level: 'info',
    message: `Received ${signal}, shutting down gracefully`,
    environment: config.server.environment,
  });

  server.close(() => {
    console.log({
      timestamp: new Date().toISOString(),
      level: 'info',
      message: 'Server shut down',
      environment: config.server.environment,
    });
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error({
      timestamp: new Date().toISOString(),
      level: 'error',
      message: 'Could not close connections in time, forcefully shutting down',
      environment: config.server.environment,
    });
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

