// Secure Express Application
// Implements security best practices

require('dotenv').config();  // Load environment variables

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// 3. Basic Security Middleware
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Remove X-Powered-By header
app.disable('x-powered-by');

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Users endpoint with input validation
app.get('/users', 
  // Input validation
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
  ],
  (req, res) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Simulated user data (in production, this would come from a database)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user'
      },
    ];

    // Filter sensitive data before sending response
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name
      // Note: We're intentionally not sending email in response
    }));

    res.json({
      success: true,
      data: safeUsers,
      count: safeUsers.length,
      timestamp: new Date().toISOString()
    });
  }
);

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal Server Error' : err.message,
    message: isProduction ? 'An unexpected error occurred' : err.stack,
    timestamp: new Date().toISOString()
  });
});

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handler
const server = app.listen(PORT, HOST, () => {
  console.log(`Secure server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log('Security features enabled:');
  console.log('  ✓ Helmet.js security headers');
  console.log('  ✓ Rate limiting (100 requests/15 min per IP)');
  console.log('  ✓ Input validation');
  console.log('  ✓ Request size limits');
  console.log('  ✓ X-Powered-By header removed');
  console.log('  ✓ Sensitive data filtering');
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, server };

