// Configuration Module
// Centralized configuration with environment variable support
// Validates all required configuration at startup

require('dotenv').config();

class Config {
  constructor() {
    this.validateRequiredConfig();
    this.loadConfig();
  }

  // Validate that required environment variables are set
  validateRequiredConfig() {
    const required = ['PORT'];
    const missing = [];

    for (const key of required) {
      if (!process.env[key]) {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      console.error('ERROR: Missing required environment variables:');
      for (const key of missing) {
        console.error(`  - ${key}`);
      }
      console.error('\nPlease set these variables in your .env file');
      console.error('See .env.example for required configuration');
      process.exit(1);
    }
  }

  // Load and parse configuration
  loadConfig() {
    // Server Configuration
    this.port = parseInt(process.env.PORT, 10);
    this.host = process.env.HOST || '0.0.0.0';
    this.nodeEnv = process.env.NODE_ENV || 'development';
    this.isProduction = this.nodeEnv === 'production';

    // Rate Limiting Configuration
    this.rateLimit = {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || (15 * 60 * 1000), // 15 minutes
      max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100,
      message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
    };

    // Security Headers Configuration
    this.security = {
      hstsMaxAge: parseInt(process.env.HSTS_MAX_AGE, 10) || 31536000, // 1 year in seconds
      requestSizeLimit: process.env.REQUEST_SIZE_LIMIT || '10kb',

      // Content Security Policy
      csp: {
        defaultSrc: this.parseCspDirective(process.env.CSP_DEFAULT_SRC) || ["'self'"],
        styleSrc: this.parseCspDirective(process.env.CSP_STYLE_SRC) || ["'self'"],
        scriptSrc: this.parseCspDirective(process.env.CSP_SCRIPT_SRC) || ["'self'"],
        imgSrc: this.parseCspDirective(process.env.CSP_IMG_SRC) || ["'self'", "data:", "https:"],
      },

      // Only allow unsafe-inline in development
      allowUnsafeInline: process.env.ALLOW_UNSAFE_INLINE === 'true' || !this.isProduction,
    };

    // Application Configuration
    this.app = {
      userQueryMaxLimit: parseInt(process.env.USER_QUERY_MAX_LIMIT, 10) || 100,
      logLevel: process.env.LOG_LEVEL || 'info',
      shutdownTimeout: parseInt(process.env.SHUTDOWN_TIMEOUT_MS, 10) || 30000, // 30 seconds
    };

    // Validate numeric configurations
    this.validateNumericConfig();
  }

  // Parse CSP directives from environment variable string
  parseCspDirective(value) {
    if (!value) return null;
    return value.split(',').map(v => v.trim());
  }

  // Validate numeric configuration values
  validateNumericConfig() {
    const validations = [
      { key: 'port', value: this.port, min: 1, max: 65535 },
      { key: 'rateLimit.windowMs', value: this.rateLimit.windowMs, min: 1000 }, // min 1 second
      { key: 'rateLimit.max', value: this.rateLimit.max, min: 1 },
      { key: 'security.hstsMaxAge', value: this.security.hstsMaxAge, min: 0 },
      { key: 'app.userQueryMaxLimit', value: this.app.userQueryMaxLimit, min: 1, max: 1000 },
      { key: 'app.shutdownTimeout', value: this.app.shutdownTimeout, min: 1000 },
    ];

    for (const validation of validations) {
      if (validation.value < validation.min) {
        console.error(`ERROR: ${validation.key} must be at least ${validation.min}, got ${validation.value}`);
        process.exit(1);
      }
      if (validation.max && validation.value > validation.max) {
        console.error(`ERROR: ${validation.key} must be at most ${validation.max}, got ${validation.value}`);
        process.exit(1);
      }
    }
  }

  // Get CSP directives with environment-specific adjustments
  getCspDirectives() {
    const directives = { ...this.security.csp };

    // Add unsafe-inline only if explicitly allowed (for development)
    if (this.security.allowUnsafeInline && directives.styleSrc) {
      if (!directives.styleSrc.includes("'unsafe-inline'")) {
        directives.styleSrc = [...directives.styleSrc, "'unsafe-inline'"];
      }
    }

    return directives;
  }

  // Log configuration (safe version - doesn't log secrets)
  logConfig() {
    console.log('=== Configuration Loaded ===');
    console.log(`Environment: ${this.nodeEnv}`);
    console.log(`Server: http://${this.host}:${this.port}`);
    console.log('');
    console.log('Rate Limiting:');
    console.log(`  Window: ${this.rateLimit.windowMs}ms (${this.rateLimit.windowMs/60000} minutes)`);
    console.log(`  Max Requests: ${this.rateLimit.max}`);
    console.log('');
    console.log('Security:');
    console.log(`  HSTS Max Age: ${this.security.hstsMaxAge} seconds`);
    console.log(`  Request Size Limit: ${this.security.requestSizeLimit}`);
    console.log(`  Allow Unsafe Inline: ${this.security.allowUnsafeInline}`);
    console.log('');
    console.log('Application:');
    console.log(`  User Query Max Limit: ${this.app.userQueryMaxLimit}`);
    console.log(`  Log Level: ${this.app.logLevel}`);
    console.log('============================\n');
  }
}

// Create and export singleton instance
const config = new Config();
module.exports = config;

