  contentSecurityPolicy: {
    directives: config.getCspDirectives(),
  },
  hsts: config.security.hstsMaxAge > 0 ? {
    maxAge: config.security.hstsMaxAge,
    includeSubDomains: true,
    preload: true
  } : false, // Disable HSTS if maxAge is 0
}));

// 2. Rate Limiting (from config)
const apiLimiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: config.rateLimit.message,
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// 3. Basic Security Middleware
app.use(express.json({ limit: config.security.requestSizeLimit }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.security.requestSizeLimit 
}));

// 4. Remove X-Powered-By header
app.disable('x-powered-by');

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv,
    config: {
      port: config.port,
      rateLimit: {
        windowMinutes: config.rateLimit.windowMs / 60000,
        maxRequests: config.rateLimit.max
      }
    }
  });
});

// Users endpoint with configurable validation
app.get('/users', 
  // Input validation with configurable limits
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ 
      min: 1, 
      max: config.app.userQueryMaxLimit 
    }).withMessage(`Limit must be between 1 and ${config.app.userQueryMaxLimit}`)
  ],
  (req, res) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation Error',
        errors: errors.array(),
        timestamp: new Date().toISOString()
      });
    }

    // Get query parameters with defaults
    const page = parseInt(req.query.page, 10) || 1;
    const limit = parseInt(req.query.limit, 10) || 10;

    // Simulated user data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user',
        createdAt: new Date('2023-01-01')
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user',
        createdAt: new Date('2023-01-02')
      },
      { 
        id: 3, 
        name: 'Charlie', 
        email: 'charlie@example.com',
        role: 'admin',
        createdAt: new Date('2023-01-03')
      },
    ];

    // Apply pagination (simplified for example)
    const startIndex = (page - 1) * limit;
    const endIndex = Math.min(startIndex + limit, users.length);
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Filter sensitive data before sending response
    const safeUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      role: user.role,
      // Note: We're intentionally not sending email in response
    }));

    res.json({
      success: true,
      data: safeUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit),
        hasNext: endIndex < users.length,
        hasPrev: page > 1
      },
      timestamp: new Date().toISOString()
    });
  }
);

// Configuration endpoint (development only)
if (!config.isProduction) {
  app.get('/config', (req, res) => {
    res.json({
      environment: config.nodeEnv,
      server: {
        port: config.port,
        host: config.host
      },
      rateLimit: config.rateLimit,
      security: {
        hstsMaxAge: config.security.hstsMaxAge,
        requestSizeLimit: config.security.requestSizeLimit,
        csp: config.security.csp,
        allowUnsafeInline: config.security.allowUnsafeInline
      },
      app: {
        userQueryMaxLimit: config.app.userQueryMaxLimit,
        logLevel: config.app.logLevel
      }
    });
  });
}

// ========== ERROR HANDLING ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with configured log level
  if (config.app.logLevel === 'debug' || config.app.logLevel === 'info') {
    console.error(`[${config.nodeEnv.toUpperCase()}] Error:`, {
      message: err.message,
      stack: config.app.logLevel === 'debug' ? err.stack : undefined,
      path: req.path,
      method: req.method,
      timestamp: new Date().toISOString()
    });
  }

  // Don't leak error details in production
  const errorResponse = config.isProduction ? {
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
    timestamp: new Date().toISOString()
  } : {
    error: err.message,
    message: err.stack,
    timestamp: new Date().toISOString()
  };

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER STARTUP ==========

// Log configuration at startup
config.logConfig();

// Create server
const server = app.listen(config.port, config.host, () => {
  console.log(`Server running on http://${config.host}:${config.port}`);
  console.log(`Environment: ${config.nodeEnv}`);
  console.log('');
  console.log('Security Features:');
  console.log(`  ✓ Helmet.js with configurable CSP`);
  console.log(`  ✓ HSTS: ${config.security.hstsMaxAge > 0 ? 'Enabled' : 'Disabled'}`);
  console.log(`  ✓ Rate limiting: ${config.rateLimit.max} requests per ${config.rateLimit.windowMs/60000} minutes`);
  console.log(`  ✓ Request size limit: ${config.security.requestSizeLimit}`);
  console.log(`  ✓ Input validation with configurable limits`);
  console.log(`  ✓ X-Powered-By header removed`);
  console.log(`  ✓ Production-safe error handling`);
});

// Graceful shutdown with configurable timeout
const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error(`Forcing shutdown after ${config.app.shutdownTimeout}ms timeout`);
    process.exit(1);
  }, config.app.shutdownTimeout);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  if (!config.isProduction) {
    shutdown('UNHANDLED_REJECTION');
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  if (!config.isProduction) {
    shutdown('UNCAUGHT_EXCEPTION');
  }
});

module.exports = { app, server, config };

