// Secure Express application with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// General rate limiter for all routes
app.use(apiLimiter);

// 4. Body parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========== AUTHENTICATION MIDDLEWARE (Placeholder) ==========
// In production, implement proper authentication (JWT, sessions, etc.)
const authenticate = (req, res, next) => {
  // This is a placeholder - implement real authentication
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const token = authHeader.substring(7);
  // Verify token here (e.g., using jsonwebtoken)
  // For now, we'll just check for a dummy token
  if (token !== 'valid-token-placeholder') {
    return res.status(403).json({ error: 'Invalid token' });
  }

  req.user = { id: 1, role: 'user' }; // Set user from token
  next();
};

// ========== ERROR HANDLING MIDDLEWARE ==========
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak stack traces in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal server error',
      message: 'Something went wrong'
    });
  }

  res.status(500).json({ 
    error: err.message,
    stack: err.stack
  });
});

// ========== ROUTES ==========

// Public route - no authentication required
app.get('/health', [
  query('detailed').optional().isBoolean().toBoolean()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const response = { 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  if (req.query.detailed) {
    response.environment = process.env.NODE_ENV || 'development';
    response.nodeVersion = process.version;
  }

  res.json(response);
});

// Protected route - requires authentication
app.get('/users', authenticate, [
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt()
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const limit = req.query.limit || 10;
  const offset = req.query.offset || 0;

  // Sample data - in production, fetch from database
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      role: 'user',
      createdAt: '2024-01-01T00:00:00.000Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      role: 'admin',
      createdAt: '2024-01-02T00:00:00.000Z'
    },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    users: paginatedUsers,
    pagination: {
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    }
  });
});

// Create user endpoint with validation
app.post('/users', authenticate, [
  body('name').trim().notEmpty().isLength({ min: 2, max: 50 }),
  body('email').trim().isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }).matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
    .withMessage('Password must contain at least one uppercase letter, one lowercase letter, and one number')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // In production, hash password before storing
  const { name, email } = req.body;

  // Create user in database
  const newUser = {
    id: Date.now(), // Use proper ID generation in production
    name,
    email,
    createdAt: new Date().toISOString()
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

// ========== 404 HANDLER ==========
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// ========== SERVER CONFIGURATION ==========
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Validate environment variables
if (!process.env.NODE_ENV) {
  console.warn('⚠️  NODE_ENV is not set. Defaulting to "development"');
  process.env.NODE_ENV = 'development';
}

if (process.env.NODE_ENV === 'production' && !process.env.ALLOWED_ORIGINS) {
  console.error('❌ ALLOWED_ORIGINS must be set in production environment');
  process.exit(1);
}

app.listen(PORT, HOST, () => {
  console.log(`Server running in ${process.env.NODE_ENV} mode`);
  console.log(`Listening on http://${HOST === '0.0.0.0' ? 'localhost' : HOST}:${PORT}`);

  // Security checklist on startup
  if (process.env.NODE_ENV === 'production') {
    console.log('🔒 Security features enabled:');
    console.log('  ✓ Helmet security headers');
    console.log('  ✓ CORS with origin restrictions');
    console.log('  ✓ Rate limiting (100 requests/15min per IP)');
    console.log('  ✓ Input validation');
    console.log('  ✓ Authentication required for protected routes');
  }
});

module.exports = app;

